VAULT = ""   # generated: set by configure(vault_root)
WINDOWS = ["10:00", "15:00", "18:00"]          # 시간대 시작 — 각 시간대는 시작부터 60분(끝 시각 포함, 10분 단위 7개). CUTOVER 전 날짜
NEW_WINDOWS = ["10:00", "13:00", "16:00"]      # 2026-11-11 Thomas: CUTOVER 날부터 일반 글 시간대
FAST_CHOICES = ["19:10", "19:20", "19:30", "19:40", "19:50"]   # 빠른 글 — 19~20시 안(옛 저녁 칸 끝 19:00과 겹치지 않게)
CUTOVER = "2026-11-22"                          # 네이버 예약이 11-21(209편)까지 — 그 뒤 날짜부터 새 시간대
DAY_MAX = 3                                     # 일반 글 하루 상한(kw_pipeline이 naver_reserve의 같은 값을 하루 발행 수로 읽는다 — 올리지 않는다)
FAST_MAX = 1                                    # 빠른 글 하루 상한(일반 글과 따로 센다)
SINCE = 161                                     # 이 편부터 fix 대상(160편까지는 10-23에 예약표로 맞췄다)


def windows_for(date: str) -> list[str]:
    return NEW_WINDOWS if date >= CUTOVER else WINDOWS


def is_fast(d: dict) -> bool:
    return str(d.get("fast", "")).strip().lower() in ("true", "yes", "1")


def choices(w: int, date: str = "") -> list[str]:
    h, m = map(int, windows_for(date)[w].split(":"))
    return [f"{(h * 60 + m + k) // 60:02d}:{(h * 60 + m + k) % 60:02d}" for k in range(0, 61, 10)]


def window_of(hm: str) -> int:
    """'HH:MM' → 시간대(0 아침 · 1 점심 · 2 저녁). 옛 시간대(10:30~12:00 · 15:00~16:30 · 18:30~20:00)도 같은 칸으로 본다."""
    h = int(hm[:2])
    return 0 if h < 13 else 1 if h < 17 else 2


def pick(name: str, date: str, w: int) -> str:
    """같은 파일·날짜·시간대면 늘 같은 분. 이름은 경로 없이 파일 이름. w == -9는 빠른 글 칸."""
    c = FAST_CHOICES if w == -9 else choices(w, date)
    return c[int(hashlib.md5(f"{os.path.basename(name)}|{date}|{w}".encode()).hexdigest(), 16) % len(c)]


def new_window_of(hm: str) -> int:
    """CUTOVER 뒤 날짜의 시각 → 칸(0·1·2 일반, 3 빠른 19시대). 칸 밖 시각은 -2."""
    h = int(hm[:2])
    return {10: 0, 11: 0, 13: 1, 14: 1, 16: 2, 17: 2, 19: 3, 20: 3}.get(h, -2)


def kst_today() -> dt.date:
    return dt.datetime.now(dt.timezone(dt.timedelta(hours=9))).date()


def fm(text: str) -> dict:
    m = re.match(r"---\n(.*?)\n---", text, re.S)
    out = {}
    for line in (m.group(1).splitlines() if m else []):
        k = re.match(r"([A-Za-z_]+):\s*(.*)$", line)
        if k:
            out[k.group(1)] = re.sub(r"\s+#.*$", "", k.group(2)).strip().strip('"')
    return out


def drafts(vault: str) -> list[tuple[str, dict]]:
    files = glob.glob(os.path.join(vault, "content/naver/*.md")) + glob.glob(os.path.join(vault, "content/naver/제휴/*.md"))
    return [(f, fm(open(f, encoding="utf-8").read())) for f in sorted(files)]


def episode(path: str) -> int | None:
    m = re.match(r"0*(\d+)편-", os.path.basename(path))
    return int(m.group(1)) if m else None




def when(v: str) -> tuple[str, str | None] | None:
    m = re.match(r"(\d{4}-\d{2}-\d{2})(?:\s+(\d{2}:\d{2}))?", v or "")
    return (m.group(1), m.group(2)) if m else None


FAST_LAST_HOUR = 17   # 이 시각(KST) 뒤에 돌리면 그날 저녁은 맥이 저장·예약할 틈이 없다 — 다음 날부터


def next_fast(vault: str, file: str, today: dt.date | None = None) -> str:
    """빠른 글의 'YYYY-MM-DD HH:MM' — 원고를 쓴 그날 19:10~19:50부터(Thomas 2026-11-11 '당일 저녁부터 순차적으로').
    FAST_LAST_HOUR(17시) 뒤에 돌리면 다음 날부터. 그날 빠른 글이 이미 FAST_MAX편(draft·hold·예약)이면 다음 날, 차례로.
    today를 주면 그 날짜를 '쓴 날'로 본다(시각 보정 없음 — 슬롯 그림자는 원고의 created를 준다). 이 파일 자신은 세지 않는다."""
    me = os.path.basename(file)
    now = dt.datetime.now(dt.timezone(dt.timedelta(hours=9)))
    base = today or (now.date() + dt.timedelta(days=1) if now.hour >= FAST_LAST_HOUR else now.date())
    taken: dict[str, int] = {}
    for f, d in drafts(vault):
        if os.path.basename(f) == me or not is_fast(d) or d.get("status") not in ("draft", "hold", "scheduled"):
            continue
        w = when(d.get("scheduled", ""))
        if w:
            taken[w[0]] = taken.get(w[0], 0) + 1
    day = base
    while taken.get(day.isoformat(), 0) >= FAST_MAX:
        day += dt.timedelta(days=1)
    return f"{day.isoformat()} {pick(me, day.isoformat(), -9)}"


def next_slot(vault: str, file: str) -> str:
    """새 원고 한 편의 'YYYY-MM-DD HH:MM'. 이 파일 자신은 세지 않는다. 빠른 글은 세지 않는다(next_fast)."""
    me = os.path.basename(file)
    days: dict[str, set[int]] = {}
    for f, d in drafts(vault):
        if os.path.basename(f) == me or d.get("status") != "draft" or is_fast(d):
            continue
        w = when(d.get("scheduled", ""))
        if w:
            days.setdefault(w[0], set()).add(len(days.get(w[0], ())) if w[1] and w[0] >= CUTOVER else window_of(w[1]) if w[1] else -1)
    if not days:
        raise SystemExit("draft 원고에 scheduled 날짜가 하나도 없다 — 시작 날짜를 손으로 정한다")
    last = max(days)
    used = days[last]
    date = last
    if len(used) >= DAY_MAX or -1 in used:   # 시각 없는 날은 꽉 찬 것으로 본다(모르면 막는 쪽)
        date = (dt.date.fromisoformat(last) + dt.timedelta(days=1)).isoformat()
        used = set()
    w = min(set(range(len(WINDOWS))) - used)
    return f"{date} {pick(me, date, w)}"




def clashes(vault: str) -> list[str]:
    """같은 날 같은 시간대에 두 편, 또는 하루 DAY_MAX편 넘게 잡힌 draft·hold. 10-25 수동 실행: hold 166편(11-07 10:10)과
    draft 167편(11-07 10:20)이 같은 아침 칸이었다 — next는 hold를 세지 않는다. hold를 draft로 돌릴 때 next로 자리를 다시 받는다."""
    seen: dict[str, list[tuple[int, str]]] = {}
    fast: dict[str, list[str]] = {}
    for f, d in drafts(vault):
        if d.get("status") not in ("draft", "hold"):
            continue
        w = when(d.get("scheduled", ""))
        if w and w[1]:
            name = f"{os.path.basename(f)[:-3]}({d['status']} {w[1]})"
            if is_fast(d):
                fast.setdefault(w[0], []).append(name)
                if w[1] not in FAST_CHOICES:
                    seen.setdefault(w[0], [])   # 날짜만 남긴다
                    fast.setdefault("_off", []).append(f"{w[0]} 빠른 글이 19:10~19:50 밖: {name}")
                continue
            seen.setdefault(w[0], []).append((new_window_of(w[1]) if w[0] >= CUTOVER else window_of(w[1]), name))
    out = []
    labels = {0: "아침", 1: "점심", 2: "저녁", 3: "19시(빠른 글 칸)", -2: "칸 밖"}
    for day, rows in sorted(seen.items()):
        by = {}
        for win, name in rows:
            by.setdefault(win, []).append(name)
        out += [f"{day} {labels[win]} 칸에 {len(ns)}편: {', '.join(ns)}" for win, ns in sorted(by.items()) if len(ns) > 1 or win in (3, -2)]
        if len(rows) > DAY_MAX:
            out.append(f"{day} 하루 {len(rows)}편(상한 {DAY_MAX}): {', '.join(n for _, n in rows)}")
    out += [f"{day} 빠른 글 {len(ns)}편(상한 {FAST_MAX}): {', '.join(ns)}" for day, ns in sorted(fast.items()) if day != "_off" and len(ns) > FAST_MAX]
    out += fast.get("_off", [])
    return out


